def transform(grid):
    h, w = len(grid), len(grid[0])
    # The colored full-width/full-height lines partition the canvas into equal cells.
    colors = {v for row in grid for v in row}
    sep = None
    # Select line color that forms the most complete internal row/column dividers.
    best = -1
    for c in colors:
        rows = [r for r in range(h) if all(grid[r][x] == c for x in range(w))]
        cols = [x for x in range(w) if all(grid[y][x] == c for y in range(h))]
        score = len(rows) + len(cols)
        if score > best:
            best, sep = score, c
    divrows = [r for r in range(h) if all(grid[r][x] == sep for x in range(w))]
    divcols = [x for x in range(w) if all(grid[y][x] == sep for y in range(h))]
    # Cell bounds exclude divider lines.
    rbounds = [-1] + divrows + [h]
    cbounds = [-1] + divcols + [w]
    cells = []
    for ri in range(len(rbounds)-1):
        r0, r1 = rbounds[ri]+1, rbounds[ri+1]
        for ci in range(len(cbounds)-1):
            c0, c1 = cbounds[ci]+1, cbounds[ci+1]
            cells.append((r0, r1, c0, c1))
    bg = max(colors, key=lambda c: sum(v == c for row in grid for v in row))
    sources = []
    for r0,r1,c0,c1 in cells:
        patch = [row[c0:c1] for row in grid[r0:r1]]
        if any(v != bg for row in patch for v in row):
            sources.append((r0,r1,c0,c1,patch))
    out = [row[:] for row in grid]
    if sources:
        # In these puzzles one compartment contains the template; fill the matching empty compartments.
        r0,r1,c0,c1,patch = sources[0]
        for rr0,rr1,cc0,cc1 in cells:
            if (rr1-rr0, cc1-cc0) != (r1-r0, c1-c0):
                continue
            for dy in range(r1-r0):
                for dx in range(c1-c0):
                    if patch[dy][dx] != bg:
                        out[rr0+dy][cc0+dx] = patch[dy][dx]
    return out
